package service

import (
	"context"
	"fmt"
	"time"

	"evalfixture/clock"
	"evalfixture/repository"
)

// Session grants access until ExpiresAt.
type Session struct {
	Email     string
	ExpiresAt time.Time
}

type AccessService struct {
	users      repository.UserRepository
	sessionTTL time.Duration
	clock      clock.Clock
}

func NewAccessService(users repository.UserRepository, sessionTTL time.Duration, clock clock.Clock) *AccessService {
	return &AccessService{users: users, sessionTTL: sessionTTL, clock: clock}
}

func (s *AccessService) GrantSession(ctx context.Context, email string) (Session, error) {
	user, err := s.users.GetByEmail(ctx, email)
	if err != nil {
		return Session{}, fmt.Errorf("granting session: %w", err)
	}
	return Session{
		Email:     user.Email(),
		ExpiresAt: s.clock.Now().Add(s.sessionTTL),
	}, nil
}

func (s *AccessService) IsSessionValid(session Session) bool {
	return session.ExpiresAt.After(s.clock.Now())
}

package service_test

import (
	"context"
	"testing"
	"time"

	"github.com/stretchr/testify/suite"

	"evalfixture/clock"
	"evalfixture/domaintest"
	"evalfixture/repository"
	"evalfixture/repository/fakes"
	"evalfixture/service"
)

type accessServiceSuite struct {
	suite.Suite
	ctx     context.Context
	users   *fakes.FakeUserRepository
	clock   *clock.FrozenClock
	service *service.AccessService
}

func TestAccessServiceSuite(t *testing.T) {
	suite.Run(t, new(accessServiceSuite))
}

func (s *accessServiceSuite) SetupTest()    { s.init() }
func (s *accessServiceSuite) SetupSubTest() { s.init() }

func (s *accessServiceSuite) init() {
	s.ctx = context.Background()
	s.users = fakes.NewFakeUserRepository()
	s.clock = clock.NewFrozenClock(time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC))
	s.service = service.NewAccessService(s.users, time.Hour, s.clock)
}

func (s *accessServiceSuite) Test_GrantSession_ReturnsSessionForKnownUser() {
	user := domaintest.NewUnpersistedUser(domaintest.WithEmail("known@example.com"))
	_, err := s.users.Save(s.ctx, user)
	s.Require().NoError(err)

	session, err := s.service.GrantSession(s.ctx, "known@example.com")

	s.NoError(err)
	s.Equal("known@example.com", session.Email)
	s.False(session.ExpiresAt.IsZero())
}

func (s *accessServiceSuite) Test_GrantSession_UsesClockForExpiry() {
	user := domaintest.NewUnpersistedUser(domaintest.WithEmail("known@example.com"))
	_, err := s.users.Save(s.ctx, user)
	s.Require().NoError(err)

	session, err := s.service.GrantSession(s.ctx, "known@example.com")

	s.NoError(err)
	s.Equal(s.clock.Now().Add(time.Hour), session.ExpiresAt)
}

func (s *accessServiceSuite) Test_GrantSession_ErrorsForUnknownEmail() {
	_, err := s.service.GrantSession(s.ctx, "stranger@example.com")

	s.ErrorIs(err, repository.ErrNotFound)
}

func (s *accessServiceSuite) Test_IsSessionValid_FutureExpiry() {
	session := service.Session{Email: "known@example.com", ExpiresAt: s.clock.Now().Add(time.Hour)}

	s.True(s.service.IsSessionValid(session))
}

func (s *accessServiceSuite) Test_IsSessionValid_PastExpiry() {
	session := service.Session{Email: "known@example.com", ExpiresAt: s.clock.Now().Add(-time.Hour)}

	s.False(s.service.IsSessionValid(session))
}

func (s *accessServiceSuite) Test_IsSessionValid_ExpiresExactlyNow() {
	session := service.Session{Email: "known@example.com", ExpiresAt: s.clock.Now()}

	s.False(s.service.IsSessionValid(session))
}
